SELECT jsonb_build_object('account',current_user,'roles',(SELECT jsonb_agg(to_jsonb(r)) FROM (SELECT rolname,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole FROM pg_roles WHERE rolname IN('hb_app','hb_report','hb_maintenance') OR oid IN(SELECT roleid FROM pg_auth_members WHERE member IN(SELECT oid FROM pg_roles WHERE rolname IN('hb_app','hb_report','hb_maintenance'))) ORDER BY rolname)r),'memberships',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT r.rolname AS member,g.rolname AS group_role FROM pg_auth_members m JOIN pg_roles r ON r.oid=m.member JOIN pg_roles g ON g.oid=m.roleid WHERE r.rolname IN('hb_app','hb_report','hb_maintenance') ORDER BY 1,2)x));
